package cn.huankan.event;
import java.util.*;import java.nio.charset.StandardCharsets;import cn.huankan.evidence.EvidenceService;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;
@Service public class WatchService {private final JdbcTemplate db;public WatchService(JdbcTemplate d){db=d;}public static String owner(String authorization){if(authorization==null||!authorization.startsWith("Bearer ")||authorization.length()<15)throw new IllegalArgumentException("用户身份未确认");return EvidenceService.hash(authorization.getBytes(StandardCharsets.UTF_8));}
 public record Add(String kind,String value,String label,boolean includeLeads,int minimumPriority){}
 public Object list(String owner){return db.queryForList("SELECT id,kind,value,label,include_leads,minimum_priority,enabled,created_at FROM user_watch WHERE owner_key=? ORDER BY created_at DESC LIMIT 100",owner);}
 public Object add(String owner,Add q){if(q.kind()==null||q.value()==null||q.value().isBlank()||q.value().length()>200||q.label()==null||q.label().isBlank()||q.label().length()>200||q.minimumPriority()<0||q.minimumPriority()>100)throw new IllegalArgumentException("关注条件无效");boolean known=switch(q.kind()){case "EVENT"->q.value().matches("[a-fA-F0-9-]{36}")&&exists("SELECT EXISTS(SELECT 1 FROM financial_event WHERE id::text=?)",q.value());case "SOURCE"->exists("SELECT EXISTS(SELECT 1 FROM source_registry WHERE id=?)",q.value());case "CENTRAL_BANK"->Set.of("FED","ECB").contains(q.value());case "COUNTRY"->exists("SELECT EXISTS(SELECT 1 FROM source_registry WHERE region=?)",q.value());case "INDICATOR"->exists("SELECT EXISTS(SELECT 1 FROM macro_series WHERE id=? UNION ALL SELECT 1 FROM bls_series_config WHERE id=? AND verified)",q.value(),q.value());case "INSTITUTION"->exists("SELECT EXISTS(SELECT 1 FROM source_registry WHERE name=? UNION ALL SELECT 1 FROM financial_entity WHERE official_name=?)",q.value(),q.value());case "COMPANY"->exists("SELECT EXISTS(SELECT 1 FROM financial_entity e JOIN gleif_legal_record g ON g.entity_id=e.id WHERE e.type='COMPANY' AND g.lei=?)",q.value());case "EVENT_TYPE"->exists("SELECT EXISTS(SELECT 1 FROM financial_event WHERE category=?)",q.value());case "INDUSTRY"->exists("SELECT EXISTS(SELECT 1 FROM governed_message WHERE topics ?? ?)",q.value());default->false;};if(!known)throw new IllegalArgumentException("关注目标未在真实数据目录中确认");if(db.queryForObject("SELECT count(*) FROM user_watch WHERE owner_key=? AND enabled",Long.class,owner)>=100)throw new IllegalArgumentException("关注名单上限100项");db.update("INSERT INTO user_watch(id,owner_key,kind,value,label,include_leads,minimum_priority) VALUES(?,?,?,?,?,?,?) ON CONFLICT(owner_key,kind,value) DO UPDATE SET enabled=true,label=excluded.label,include_leads=excluded.include_leads,minimum_priority=excluded.minimum_priority",UUID.randomUUID(),owner,q.kind(),q.value(),q.label(),q.includeLeads(),q.minimumPriority());return list(owner);}
 private boolean exists(String sql,Object... args){return Boolean.TRUE.equals(db.queryForObject(sql,Boolean.class,args));}
 public Object remove(String owner,UUID id){db.update("UPDATE user_watch SET enabled=false WHERE id=? AND owner_key=?",id,owner);return list(owner);}
 public Object catalog(){return Map.of("sources",db.queryForList("SELECT id,name,region,level FROM source_registry ORDER BY id"),"indicators",db.queryForList("SELECT id,title FROM macro_series ORDER BY id"),"companies",db.queryForList("SELECT DISTINCT g.lei id,e.official_name title FROM financial_entity e JOIN gleif_legal_record g ON g.entity_id=e.id WHERE e.type='COMPANY' ORDER BY e.official_name LIMIT 100"),"event_types",db.queryForList("SELECT DISTINCT category id,category title FROM financial_event ORDER BY category"),"topics",db.queryForList("SELECT DISTINCT jsonb_array_elements_text(topics) id FROM governed_message LIMIT 100"));}
 public Object radar(String owner,int page){if(page<0||page>100000)throw new IllegalArgumentException("关注雷达分页无效");return db.queryForList("SELECT e.id,e.original_title,e.source_id,s.name publisher,s.level,r.source_url,r.published_at,r.collected_at,r.ingestion_kind,COALESCE(g.priority,0) priority,COALESCE(q.message_class,'SOURCE_EVENT') message_class,q.qualified,q.rejection_reason,COALESCE(g.topics,'[]'::jsonb) topics,'关注规则匹配，不等同重大资格或真实企业业务关系' match_basis FROM financial_event e JOIN raw_evidence r ON r.id=e.evidence_id JOIN source_registry s ON s.id=e.source_id LEFT JOIN governed_message g ON g.event_id=e.id LEFT JOIN LATERAL(SELECT * FROM qualification_explanation x WHERE x.event_id=e.id ORDER BY x.id DESC LIMIT 1)q ON true WHERE watch_matches(?,r.id,e.id,e.source_id,s.level,COALESCE(g.priority,0)) ORDER BY s.level,COALESCE(g.priority,0) DESC,r.collected_at DESC,e.id LIMIT 50 OFFSET ?",owner,page*50);}
}
